await sdk.messages.registerRenderer('todo', entry => ({ type: 'stack', id: 'root', direction: 'horizontal', gap: 8, children: [{ type: 'badge', id: 'b', text: 'todo', tone: 'info' }, { type: 'text', id: 't', text: String(entry.data && entry.data.text || '') }] }));

async function refresh() {
  try {
    const ctx = await sdk.context.get();
    if (!ctx.sessionId) return await sdk.slots.remove('footer', 'count');
    const n = await sdk.server.call('todo', 'count', null, ctx.sessionId);
    await sdk.slots.set('footer', 'count', { label: 'Todo 개수', view: { type: 'text', id: 'c', text: `할 일 ${n}개`, size: 'small' } });
  } catch (e) {
    console.error('todo-view: refresh failed: ' + e.message);
    await sdk.slots.remove('footer', 'count');
  }
}
await refresh();
await sdk.server.on(e => { if (e.kind === 'entry' && e.type === 'todo') return refresh(); });
await sdk.events.on(e => { if (e.type === 'run_finished' || e.type === 'session_updated') return refresh(); });

await sdk.composerFilter.set(text => /\b(sk-[A-Za-z0-9]{20,}|ghp_[A-Za-z0-9]{30,})\b/.test(text) ? { cancel: '토큰처럼 보이는 문자열이 들어 있어 보내지 않았습니다' } : null);
